"""Acte V — parcours complet des Pics du Vent (arrivée -> phare -> fin d'acte). Port 8872.
   Usage : flock /tmp/lumen-chrome.lock timeout 900 python3 -u tests/qa_pics_full.py [partie]   (1 = Col+Courants, 2 = Pentes+Moulin, 3 = Sommets+Phare, all)"""
from qa_pics_lib import *
part = sys.argv[1] if len(sys.argv) > 1 else 'all'
q = new('pics-complet'); J = q.js
arrive(q)
# ---------- 1. Le Col
J('Borée : accueil', "T.talkTo('boree')", "near")
J('q_pics: étape', "T.q('q_pics')", "active:voile")
J('Alizée : voile', "(async()=>{await T.talkTo('alizee');const L=__lumen;return T.q('q_pics')+' planer='+L.st.player.abilities.planer+' voile='+L.st.inv.voile_vent+' b_courants='+T.gate('b_courants')})()", "planer=true")
J('Pierre de vent sans voile corrigée', "T.q('q_pics')", "active:courants")
# ---------- 2. Les Courants (planer réel, énigmes, relais temporisés)
J('cr1 : planer réel', "(async()=>{const L=__lumen;L.tpZone('cr1');await T.tick(500);return await T.ventsAll('cr1')})()", lambda r: 'KO' not in r and 'cible?' not in r and 'pos?' not in r and 'ok' in r)
J('cr1 : énigme pg1', "T.solve('pg1')", lambda r: r is True)
J('cr2 : planer réel', "(async()=>{const L=__lumen;L.tpZone('cr2');await T.tick(500);return await T.ventsAll('cr2')})()", lambda r: 'KO' not in r and 'cible?' not in r and 'pos?' not in r and 'ok' in r)
J('cr2 : énigme pg2', "T.solve('pg2')", lambda r: r is True)
J('cr3 : planer réel', "(async()=>{const L=__lumen;L.tpZone('cr3');await T.tick(500);return await T.ventsAll('cr3')})()", lambda r: 'KO' not in r and 'cible?' not in r and 'pos?' not in r)
J('cr3 : relais temporisés (séquence chronométrée)', "T.solveTimed('cr3')", "pg3")
J('cr3 : pg3 ouverte', "T.gate('pg3')+' '+T.q('q_pics')", "true active:terrasse")
J('cr3 : relais se rééteignent', "(async()=>{const L=__lumen;for(let i=0;i<60;i++)L.mech.tick(0.5);await T.tick(100);return L.isl.ents.filter(e=>e.t==='relay'&&e.hold&&e.heldT>0&&!e.live).length+' relais encore allumés ; pg3='+T.gate('pg3')})()", "0 relais")
J('Terrasse', "(async()=>{__lumen.tpZone('gir');await T.tick(900);return T.q('q_pics')})()", "active:retour")
J('Fil de fer : respawn vide -> retour pierre', "T.info()")
J('Borée : pentes', "(async()=>{const b=T.pre();__lumen.tpZone('col');await T.tick(600);await T.talkTo('boree');return T.q('q_pics')+' '+T.q('q_moulins')+' b_pentes='+T.gate('b_pentes')+' ecus+'+(__lumen.st.player.ecus-b.ecus)+' xp+'+(__lumen.st.player.xp-b.xp)})()", "done")
J('sauvegarde / rechargement', "T.roundtrip5('s3')", "identique")
J('relecture : planer conservé', "__lumen.st.player.abilities.planer+' '+T.gate('pg3')+' '+T.gate('b_courants')", "true true true")
if part == '1': q.done(); sys.exit()
# ---------- 3. Les Pentes : boutique, forge, quêtes secondaires
ASK = "(n,l)=>{const t=l[l.length-1];const i=t.findIndex(x=>x.includes('besoin'));return i<0?t.length-1:i}"
J('Frimas : boutique', "(async()=>{await T.talkTo('frimas',(n,l)=>0);return T.shopBuy('frimas')})()", "lignes")
J('Frimas : arme achetée', "(async()=>{const L=__lumen;L.st.player.ecus=3000;L.G.screens.shop('frimas',false);await T.tick(200);const bs=[...document.querySelectorAll('#screen [data-buy]')];const b=bs.find(x=>/Épée|Lame|givre/i.test(x.closest('li').textContent))||bs[0];b.click();await T.tick(150);L.G.screens.close();return Object.keys(L.st.inv).filter(k=>/epee|lame|givre/.test(k)).join(',')})()")
J('Frimas : forge', "(async()=>{const L=__lumen;L.G.screens.forge('frimas');await T.tick(200);const ok=!!document.querySelector('#screen');const t=document.querySelector('#screen')?document.querySelector('#screen').textContent.slice(0,80):'';L.G.screens.close();return ok+' '+t})()", "true")
J('s_chasse_pics : proposée', f"(async()=>{{await T.talkTo('frimas',{ASK});return T.q('s_chasse_pics')}})()", "active:chasse")
J('s_fleurs : proposée (Gentiane)', f"(async()=>{{__lumen.tpZone('col');await T.tick(300);await T.talkTo('gentiane',{ASK});return T.q('s_fleurs')}})()", "active:fleurs")
J('s_moulin : proposée (Tourmente)', f"(async()=>{{await T.talkTo('tourmente',{ASK});return T.q('s_moulin')}})()", "active:engrenage")
J('s_cerfvolant : proposée (Édel)', f"(async()=>{{await T.talkTo('edel',{ASK});return T.q('s_cerfvolant')}})()", "active:cerfs")
J('s_courrier : proposée (Rafale)', f"(async()=>{{await T.talkTo('rafale',{ASK});return T.q('s_courrier')+' lettres='+__lumen.st.inv.lettre_pics}})()", "lettres=3")
J('s_fanions : proposée (Alizée)', f"(async()=>{{await T.talkTo('alizee',{ASK});return T.q('s_fanions')}})()", "active:fanions")
J('s_fanions : 7 fanions (cibles réelles)', "(async()=>{const L=__lumen;let n=0;for(const pr of L.world.props.filter(p=>String(p.p.id||'').startsWith('fanion'))){const x=pr.g.position.x,z=pr.g.position.z;let ok=false;for(const [dx,dz] of [[0,1.6],[0,-1.6],[1.6,0],[-1.6,0],[1.2,1.2],[-1.2,-1.2]]) if(L.G.canStand(x+dx,z+dz)){L.P.x=x+dx;L.P.z=z+dz;L.P.vx=L.P.vz=0;for(let i=0;i<25;i++){await T.tick(60);const t=L.target();if(t&&t.kind==='fanion'&&t.pr===pr){L.interact();n++;ok=true;break}}if(ok)break}await T.tick(80)}return n+' hissés ; compte='+L.G.counts('fanions')+' '+T.q('s_fanions')})()", "active:retour")
J('s_fanions : retour', "(async()=>{const b=T.pre();await T.talkTo('alizee');return T.q('s_fanions')+' '+await T.rewardCheck('s_fanions',b)})()", "récompenses ok")
J('Pentes : arrivée', "(async()=>{__lumen.tpZone('pentes');await T.tick(900);return T.q('q_moulins')})()", "active")
J('Pentes : cueillettes réelles', "(async()=>{const o=[];for(const id of ['edel1','edel2','edel3','edel4','cerf1','engrenage1'])o.push(await T.pickupAt(id));return o.join(',')+' edel='+__lumen.st.inv.edelweiss+' '+T.q('s_moulin')})()", "ramassé")
J('s_moulin : bois (butin) + retour', "(async()=>{const L=__lumen;if((L.st.inv.bois||0)<3)L.give('bois',3);L.quests.check();const b=T.pre();L.tpZone('col');await T.tick(500);await T.talkTo('tourmente');return T.q('s_moulin')+' '+await T.rewardCheck('s_moulin',b)})()", "récompenses ok")
J('s_chasse_pics : 12 morts', "(async()=>{const L=__lumen;L.tpZone('pentes');await T.tick(1200);for(let r=0;r<6&&(L.st.stats.kills-(L.st.quests.s_chasse_pics.base.kills||0))<12;r++){await T.cutAndKill(null,25000);L.tpZone('pentes');await T.tick(600);}return (L.st.stats.kills-L.st.quests.s_chasse_pics.base.kills)+' '+T.q('s_chasse_pics')})()", "active:retour")
# ---------- 4. Le Moulin du Grand Meunier (donjon + boss)
J('Moulin : arrivée par le pont', "(async()=>{const L=__lumen;L.tpZone('moulins');await T.tick(1200);return T.q('q_moulins')+' '+T.info()})()", "active:salles")
J('Moulin : salle de combat', "(async()=>{const L=__lumen;const k=await T.cutAndKill(e=>e.room==='md_combat',40000);await T.tick(400);return k+' md_combat='+T.gate('md_combat')})()", "md_combat=true")
J('Moulin : coffre clé (cible réelle)', "T.openChest('ch_cle_m')", "ouvert:true")
J('Moulin : clé en poche', "__lumen.st.inv.cle_moulin||0", lambda r: r == 1)
J('Moulin : porte à clé (cible réelle)', "(async()=>{const L=__lumen;const z=L.G.zones[L.S.zone];L.P.x=(z.ox+15)*2;L.P.z=(z.oy+7)*2;L.P.vx=L.P.vz=0;let r='aucune';for(let i=0;i<30;i++){await T.tick(60);const t=L.target();if(t&&(t.kind==='lock'||t.kind==='door'||t.kind==='gate')){r=t.kind+':'+t.label;L.interact();break}}await T.tick(500);return r+' md_key='+T.gate('md_key')})()", "md_key=true")
J('Moulin : relais à ressort (séquence chronométrée)', "T.solveTimed('moulins')", "md_light")
J('Moulin : md_light', "T.gate('md_light')+' '+T.q('q_moulins')", "true active:meunier")
J('Moulin : coffre Épée de givre', "T.openChest('ch_tresor_m')", "ouvert:true")
J('Moulin : boss', "(async()=>{const L=__lumen;L.tpZone('moulins',[15,22]);await T.tick(1500);const r=await T.fightBoss(90000);return r+' flag='+L.st.flags.boss_meunier})()", "dead\":true")
J('Moulin : après le boss', "(async()=>{await T.tick(3500);const L=__lumen;return T.q('q_moulins')+' warp='+L.st.world.warps.moulins+' '+T.info()})()", "active:retour")
J('Moulin : coffre du cœur', "T.openChest('ch_coeur_m')", "ouvert:true")
J('Moulin : cœur en poche', "__lumen.st.inv.coeur_moulin||0", lambda r: r == 1)
J('Moulin : sauvegarde/rechargement', "T.roundtrip5('s3')", "identique")
J('Borée : cœur du moulin', "(async()=>{const b=T.pre();__lumen.tpZone('col');await T.tick(600);await T.talkTo('boree');return T.q('q_moulins')+' b_sommets='+T.gate('b_sommets')+' coeur='+(__lumen.st.inv.coeur_moulin||0)+' '+await T.rewardCheck('q_moulins',b)})()", "b_sommets=true")
J('s_chasse_pics : bilan', "T.q('s_chasse_pics')+' kills='+(__lumen.st.stats.kills-__lumen.st.quests.s_chasse_pics.base.kills)")
# ---------- 5. Les Sommets
J('Névé : arrivée', "(async()=>{const L=__lumen;L.tpZone('so1');await T.tick(1000);return T.q('q_phare_vents')})()", "active:dalle")
J('Névé : planer réel', "(async()=>{await T.tick(100);return await T.ventsAll('so1')})()", lambda r: 'KO' not in r and 'cible?' not in r and 'pos?' not in r and 'ok' in r)
J('Névé : coffres', "(async()=>{const a=await T.openChest('ch_neve1');const b=await T.openChest('ch_neve2');return a+' '+b})()", "ouvert:true ouvert:true")
J('Dalle : pont d’approche', "(async()=>{const L=__lumen;const g=L.isl.gates.b_so2;const c=g.cells[0];L.P.x=(c[0]-3)*2;L.P.z=c[1]*2;L.P.vx=L.P.vz=0;await T.tick(700);return 'b_so2='+T.gate('b_so2')})()", "true")
J('Dalle : énigme lf1 (dalles qui montent)', "(async()=>{const L=__lumen;L.tpZone('so2');await T.tick(500);const r=T.solve('lf1');await T.tick(300);return r+' '+T.q('q_phare_vents')})()", "active:cretes")
J('Dalle : retombe si on défait', "(async()=>{const L=__lumen;const d=Object.fromEntries(L.isl.ents.filter(e=>e.rot&&e.zone===L.S.zone).map(e=>[e.id,e.t==='mirror'?e.state:e.t==='lantern'?e.dir:e.out]));return JSON.stringify(Object.keys(d).length)+' objets rejouables'})()")
J('Crêtes : planer réel', "(async()=>{const L=__lumen;L.tpZone('so3');await T.tick(900);return await T.ventsAll('so3')})()", lambda r: 'KO' not in r and 'cible?' not in r and 'pos?' not in r and 'ok' in r)
J('Crêtes : coffres + corne', "(async()=>{const o=[];for(const c of ['ch_cretes1','ch_cretes2','ch_cretes3'])o.push(await T.openChest(c));o.push(await T.pickupAt('corne1'));return o.join(' ')})()", "ramassé")
J('s_corne : Flocon', f"(async()=>{{const L=__lumen;L.tpZone('auberge_p');await T.tick(500);await T.talkTo('flocon',{ASK});const a=T.q('s_corne');const b=T.pre();await T.talkTo('flocon');return a+' -> '+T.q('s_corne')+' '+await T.rewardCheck('s_corne',b)}})()", "récompenses ok")
J('Souffle court : pont + relais chronométrés', "(async()=>{const L=__lumen;const c=L.isl.gates.b_so4.cells[0];L.tpZone('so3');await T.tick(300);L.P.x=(c[0]-3)*2;L.P.z=c[1]*2;await T.tick(700);const g=T.gate('b_so4');L.tpZone('so4');await T.tick(600);return 'b_so4='+g+' '+T.solveTimed('so4')+' lf3='+T.gate('lf3')})()", "lf3=true")
J('Phare : arrivée', "(async()=>{const L=__lumen;L.tpZone('phare_v');await T.tick(1200);return T.q('q_phare_vents')+' '+T.info()})()", "active:phare")
J('Phare : porte 1', "T.solve('pv_d1')+' '+T.gate('pv_d1')", "true")
J('Phare : porte 2', "T.solve('pv_d2')+' '+T.gate('pv_d2')", "true")
J('Phare : sauvegarde en cours d’étape', "T.roundtrip5('s3')", "identique")
J('Phare : la lumière finale', "(async()=>{const L=__lumen;const r=T.solve('end');await T.tick(2500);return r+' mode='+L.S.mode+' prisme='+(L.st.inv.prisme_violet||0)})()", "prisme=1")
J('Phare : fin de la cinématique', "(async()=>{const L=__lumen;for(let i=0;i<80&&L.S.mode==='cutscene';i++)await T.tick(250);return L.S.mode+' '+T.q('q_phare_vents')})()", "active:retour")
J('Borée : fin d’acte', "(async()=>{const L=__lumen;const b=T.pre();L.tpZone('col');await T.tick(700);await T.talkTo('boree');await T.tick(1200);return T.q('q_phare_vents')+' portails='+L.st.player.abilities.portails+' acte5='+L.st.flags.acte5_fini+' écran='+L.G.screens.current+' prisme='+(L.st.inv.prisme_violet||0)+' '+await T.rewardCheck('q_phare_vents',b)})()", "acte5=1")
J('Écran de fin d’acte', "document.querySelector('#screen').textContent.slice(0,400)", "Acte 5 terminé")
J('Écran : île 6 « bientôt »', "document.querySelector('#screen .next').textContent", "bientôt")
q.done()
